import type { FilterExpression } from '@wix/sdk-types'
import type {
  WixDataItem,
  WixDataQuerySpec,
  WixDataUpdateOptions,
} from './types'

/**
 * Options builder for update operations.
 *
 * Use this builder to configure update behavior such as hooks suppression,
 * reference handling, and conditional updates.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataUpdateOptionsBuilder {
  /**
   * Sets whether to suppress update hooks.
   *
   * When `true`, the update operation runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataUpdateOptionsBuilder
  /**
   * Sets whether to include draft items when updating items.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataUpdateOptionsBuilder
  /**
   * Sets whether to include referenced items in the update response.
   * @internal
   */
  withIncludeReferences(value: boolean): WixDataUpdateOptionsBuilder
  /**
   * Sets whether to save reference values from the data item.
   */
  withSaveReferences(value: boolean): WixDataUpdateOptionsBuilder
  /**
   * Updates the item only when it matches the specified condition.
   */
  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataUpdateOptionsBuilder
  /**
   * Builds the update options object.
   */
  build(): WixDataUpdateOptions
}

class WixDataUpdateOptionsBuilderImpl implements WixDataUpdateOptionsBuilder {
  constructor(private readonly options: WixDataUpdateOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataUpdateOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataUpdateOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withIncludeReferences(value: boolean): WixDataUpdateOptionsBuilder {
    return this.copy({ includeReferences: value })
  }

  withSaveReferences(value: boolean): WixDataUpdateOptionsBuilder {
    return this.copy({ saveReferences: value })
  }

  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataUpdateOptionsBuilder {
    return this.copy({ condition: value.filter })
  }

  build(): WixDataUpdateOptions {
    return { ...this.options }
  }

  private copy(options: WixDataUpdateOptions): WixDataUpdateOptionsBuilder {
    return new WixDataUpdateOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new update options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create an update options builder"
 * import { items, Filter, UpdateOptionsBuilder } from '@wix/data'
 *
 * const options = UpdateOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .withCondition(Filter('status').eq('active'))
 *   .build()
 *
 * const updatedItem = await items.update<MyItem>(
 *   'myCollection',
 *   { _id: 'myItemId', status: 'active' },
 *   options
 * )
 * ```
 */
export const UpdateOptionsBuilder: () => WixDataUpdateOptionsBuilder = () =>
  new WixDataUpdateOptionsBuilderImpl()
